#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    sort(a.begin(), a.end());

    auto compute = [&](bool start_small) -> long long {
        deque<long long> dq(a.begin(), a.end());
        vector<long long> seq;
        bool pick_small = start_small;
        while (!dq.empty()) {
            if (pick_small) {
                seq.push_back(dq.front());
                dq.pop_front();
            } else {
                seq.push_back(dq.back());
                dq.pop_back();
            }
            pick_small = !pick_small;
        }
        long long sum = 0;
        for (int i = 1; i < n; i++) {
            sum += abs(seq[i] - seq[i-1]);
        }
        return sum;
    };

    cout << max(compute(true), compute(false)) << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<int64> A(N);
    for (int i = 0; i < N; ++i) cin >> A[i];

    sort(A.begin(), A.end());

    if (N == 1) {
        cout << 0 << '\n';
        return 0;
    }

    // For sorted array b[0..N-1], the maximum possible value can be obtained
    // by considering two optimal coefficient patterns.
    //
    // If N = 2m:
    //   ans = max(
    //       2*sum(upper m) - 2*sum(lower m) - b[m] + b[m-1],
    //       2*sum(upper m) - 2*sum(lower m) + b[m] - b[m-1]
    //   )
    //
    // If N = 2m+1:
    //   ans = max(
    //       2*sum(last m) - 2*sum(first m) + b[m] + b[m-1],
    //       2*sum(last m) - 2*sum(first m) - b[m] - b[m+1]
    //   )
    //
    // These are the standard closed forms for maximizing sum of adjacent
    // absolute differences.

    vector<int64> pref(N + 1, 0);
    for (int i = 0; i < N; ++i) pref[i + 1] = pref[i] + A[i];

    int64 ans = 0;

    if (N % 2 == 0) {
        int m = N / 2;
        int64 lower = pref[m];
        int64 upper = pref[N] - pref[m];
        int64 base = 2 * upper - 2 * lower;
        ans = max(base - A[m] + A[m - 1], base + A[m] - A[m - 1]);
    } else {
        int m = N / 2;
        int64 lower = pref[m];
        int64 upper = pref[N] - pref[m + 1];
        int64 base = 2 * upper - 2 * lower;
        ans = max(base + A[m] + A[m - 1], base - A[m] - A[m + 1]);
    }

    cout << ans << '\n';
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int cmp(const void *a, const void *b) {
    long long x = *(long long*)a, y = *(long long*)b;
    return (x > y) - (x < y);
}

int main() {
    int n;
    scanf("%d", &n);
    long long a[n];
    for (int i = 0; i < n; i++) scanf("%lld", &a[i]);
    qsort(a, n, sizeof(long long), cmp);
    long long ans = 0;
    for (int i = 0; i < n/2; i++) ans -= 2*a[i];
    for (int i = n/2; i < n; i++) ans += 2*a[i];
    // But for odd n, middle element contributes 0
    if (n % 2 == 1) ans -= 2*a[n/2]; // subtract middle once since we added it
    // Actually for odd n, middle element: added once in second loop, should contribute 0
    // n/2 for odd n: e.g. n=5, n/2=2, loop i=2,3,4 adds a[2],a[3],a[4]
    // but a[2] is middle, should not contribute. So subtract 2*a[n/2].
    printf("%lld\n", ans);
    return 0;
}

