int cmp(const void *a, const void *b) {
    return (*(int*)a - *(int*)b);
}

int main() {
    int n;
    scanf("%d", &n);
    int a[n];
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }

    qsort(a, n, sizeof(int), cmp);

    int arr[n];
    int left = 0, right = n - 1;
    for (int i = 0; i < n; i++) {
        if (i % 2 == 0) {
            arr[i] = a[left++];
        } else {
            arr[i] = a[right--];
        }
    }

    long long sum = 0;
    for (int i = 0; i < n - 1; i++) {
        sum += abs(arr[i] - arr[i + 1]);
    }

    printf("%lld\n", sum);
    return 0;
}

