typedef long long ll;

int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

ll maxll(ll a, ll b) {
    return a > b ? a : b;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    ll *A = (ll *)malloc(sizeof(ll) * N);
    for (int i = 0; i < N; i++) scanf("%lld", &A[i]);

    qsort(A, N, sizeof(ll), cmp_ll);

    if (N == 1) {
        printf("0\n");
        free(A);
        return 0;
    }

    ll ans = 0;

    if (N % 2 == 0) {
        int m = N / 2;

        ll s1 = 0, s2 = 0;
        for (int i = 0; i < m - 1; i++) s1 -= 2 * A[i];
        for (int i = m + 1; i < N; i++) s1 += 2 * A[i];
        s1 -= A[m - 1];
        s1 += A[m];

        for (int i = 0; i < m; i++) s2 -= 2 * A[i];
        for (int i = m; i < N - 1; i++) s2 += 2 * A[i];
        s2 += A[m - 1];
        s2 -= A[m];

        ans = maxll(s1, s2);
    } else {
        int m = N / 2;

        ll s1 = 0, s2 = 0;
        for (int i = 0; i < m; i++) s1 -= 2 * A[i];
        for (int i = m + 1; i < N; i++) s1 += 2 * A[i];
        s1 += A[m] - A[m - 1];

        for (int i = 0; i < m - 1; i++) s2 -= 2 * A[i];
        for (int i = m; i < N; i++) s2 += 2 * A[i];
        s2 += A[m - 1] - A[m];

        ans = maxll(s1, s2);
    }

    printf("%lld\n", ans);
    free(A);
    return 0;
}

