public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = sc.nextInt();
        }
        Arrays.sort(arr);

        List<Integer> optimal = new ArrayList<>();
        int left = 0, right = n - 1;
        while (left <= right) {
            if (left == right) {
                optimal.add(arr[left]);
                break;
            }
            optimal.add(arr[left]);
            optimal.add(arr[right]);
            left++;
            right--;
        }

        long maxSum = 0;
        for (int i = 0; i < n - 1; i++) {
            maxSum += Math.abs(optimal.get(i) - optimal.get(i + 1));
        }

        System.out.println(maxSum);
    }
}

