import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();
        long[] A = new long[N];
        for (int i = 0; i < N; i++) A[i] = fs.nextLong();

        Arrays.sort(A);

        if (N == 1) {
            System.out.println(0);
            return;
        }

        // For sorted b[0..N-1], the maximum is obtained by assigning coefficients:
        // when N = 2m:
        //   one pattern gives:
        //     -2 for b[0..m-2], -(1) for b[m-1], +(1) for b[m], +2 for b[m+1..N-1]
        //   the other pattern swaps the middle two single coefficients.
        //
        // when N = 2m+1:
        //   one pattern gives:
        //     -2 for b[0..m-1], 0 for b[m], +2 for b[m+1..N-1]
        //   but due to endpoint choices, two concrete formulas are checked.
        //
        // Standard closed forms:
        // Even:
        //   max(
        //     2*sum(upper half except first) + A[m] - (2*sum(lower half except last) + A[m-1]),
        //     2*sum(upper half) - A[m] - (2*sum(lower half) - A[m-1])
        //   )
        // Odd:
        //   max(
        //     2*sum(upper half) - 2*sum(lower half except middle) - A[m] - A[m+1],
        //     2*sum(upper half except middle) - 2*sum(lower half) + A[m] + A[m-1]
        //   )

        long[] pref = new long[N + 1];
        for (int i = 0; i < N; i++) pref[i + 1] = pref[i] + A[i];

        long ans;
        if ((N & 1) == 0) {
            int m = N / 2;

            long lowerExceptLast = pref[m - 1];          // A[0..m-2]
            long upperFromMPlus1 = pref[N] - pref[m + 1]; // A[m+1..N-1]
            long candidate1 = 2L * upperFromMPlus1 + A[m] - (2L * lowerExceptLast + A[m - 1]);

            long lowerAll = pref[m];                     // A[0..m-1]
            long upperAll = pref[N] - pref[m];           // A[m..N-1]
            long candidate2 = 2L * upperAll - A[m] - (2L * lowerAll - A[m - 1]);

            ans = Math.max(candidate1, candidate2);
        } else {
            int m = N / 2;

            long lowerAll = pref[m];                     // A[0..m-1]
            long upperAll = pref[N] - pref[m + 1];       // A[m+1..N-1]
            long candidate1 = 2L * upperAll - 2L * lowerAll + A[m] - A[m + 1];

            long lowerAll2 = pref[m + 1];                // A[0..m]
            long upperAll2 = pref[N] - pref[m + 1];      // A[m+1..N-1]
            long candidate2 = 2L * upperAll2 - 2L * (pref[m] - 0) + A[m] - A[m - 1];
            // Equivalent standard form:
            // 2*sum(A[m+1..N-1]) - 2*sum(A[0..m-1]) + A[m] - A[m-1]

            ans = Math.max(candidate1, candidate2);
        }

        System.out.println(ans);
    }
}

from itertools import permutations

def calc(arr):
    return sum(abs(arr[i]-arr[i+1]) for i in range(len(arr)-1))

n = int(input())
